CREATE TABLE agencies(id text PRIMARY KEY,name text NOT NULL,level text NOT NULL DEFAULT '基础版');
CREATE TABLE clients(id text PRIMARY KEY,agency_id text NOT NULL REFERENCES agencies(id),name text NOT NULL,UNIQUE(agency_id,name));
CREATE TABLE users(id text PRIMARY KEY,username text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('admin','agency')),agency_id text REFERENCES agencies(id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE servers(id text PRIMARY KEY,name text NOT NULL,token_hash text UNIQUE NOT NULL,last_seen timestamptz,version text,revoked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE templates(id text PRIMARY KEY,name text NOT NULL,version text NOT NULL,source_path text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version));
CREATE TABLE sites(id text PRIMARY KEY,client_id text NOT NULL REFERENCES clients(id),name text NOT NULL,domain text NOT NULL,type text NOT NULL DEFAULT '企业官网',color text NOT NULL DEFAULT '#426c5b',content jsonb NOT NULL DEFAULT '{}',revision bigint NOT NULL DEFAULT 1,api_key text UNIQUE NOT NULL,server_id text REFERENCES servers(id),template_id text NOT NULL REFERENCES templates(id),active_release text,deployed_at timestamptz);
CREATE UNIQUE INDEX sites_domain_unique ON sites(lower(domain)) WHERE domain<>'';
CREATE TABLE articles(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),external_id text,title text NOT NULL,summary text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',format text NOT NULL DEFAULT 'text' CHECK(format IN ('text','html')),status text NOT NULL CHECK(status IN ('draft','published')),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,external_id));
CREATE TABLE media(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),name text NOT NULL,object_key text,url text NOT NULL,size bigint NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE releases(id text PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,site_id text NOT NULL REFERENCES sites(id),template_id text NOT NULL REFERENCES templates(id),snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),archive_key text,sha256 text,bytes bigint,pages integer,format text NOT NULL DEFAULT 'tar-gzip-v2',error text);
CREATE TABLE build_jobs(id text PRIMARY KEY,release_id text UNIQUE NOT NULL REFERENCES releases(id),site_id text NOT NULL REFERENCES sites(id),status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX build_dispatch ON build_jobs(status,created_at);
CREATE TABLE deployment_tasks(id text PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,site_id text NOT NULL REFERENCES sites(id),server_id text NOT NULL REFERENCES servers(id),release_id text NOT NULL REFERENCES releases(id),kind text NOT NULL CHECK(kind IN ('deploy','rollback')),created_by text NOT NULL,domain text NOT NULL,status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,lease_token text,lease_until timestamptz,error text,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX deployment_claim ON deployment_tasks(server_id,status,sequence);
CREATE UNIQUE INDEX server_one_running ON deployment_tasks(server_id) WHERE status='running';
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,site_id text REFERENCES sites(id),actor text NOT NULL,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
